"""
Собирает data/chatter.json — разговоры жителей друг с другом (src/game/chatter.py).
Два соседа сходятся, поворачиваются друг к другу и по очереди говорят; кто стоит рядом — подслушивает.
  lines   [[роль, текст], ...] роли A, B (и C)
  if      условие показа (как у барков: flag / not_flag / stage / rep_ge ...)
  once    больше не повторять после подслушивания
  pair    [id, id] — именные жители: разговор только между ними (издалека, без подхода — «stay»)
  job     {"A": ["drunk"], ...} — кому по характеру подходит; без этого — любые двое
  rumor   короткий слух: попадает в «Что нового?» у городских жителей
  hint    что герой узнал, если подслушал (в журнал событий) + effects — флаги/открытие мест, помогающие в заданиях
Запуск из папки game_project:  .venv/bin/python tools/build_chatter.py
"""
import json

C = {}


def conv(town, cid, lines, **kw):
    C.setdefault(town, []).append({"id": cid, "lines": [list(l) for l in lines], **kw})


A, B, Cc = "A", "B", "C"

# ====================================================================== вся пустошь
T = "@all"
conv(T, "all_water", [(A, "Опять воду по полстакана разливают."), (B, "Лучше по полстакана, чем по полкружки крови."), (A, "Ты утешать вообще умеешь?"), (B, "Нет. Я умею считать.")],
     rumor="Вода дорожает: полстакана на душу — уже роскошь.")
