conv(T, "all_ghoul", [(A, "Гули — тоже люди."), (B, "Были. Теперь они лучше."), (A, "Чем?"), (B, "Не пьют и не дерутся. Почти.")])
conv(T, "all_dream", [(A, "Снилось, что я в Убежище. Чисто, светло, тихо."), (B, "И что?"), (A, "Проснулся — обрадовался, что я здесь.")])
