conv(T, "all_pistol", [(A, "Купил револьвер. Говорят, довоенный."), (B, "Работает?"), (A, "Не знаю. Боюсь проверять: вдруг работает.")])
conv(T, "all_snore", [(A, "Ночью кто-то храпел за стеной. Громко."), (B, "Может, это не человек?"), (A, "Если не человек — то он спокойнее наших соседей.")])
conv(T, "all_rain", [(A, "Говорят, на севере был дождь."), (B, "Настоящий?"), (A, "Кислый. Но все выбежали и стояли с открытыми ртами."), (B, "Вот это я понимаю — счастье.")])
