conv(T, "sl_miner", [(A, "Шахтёр Билл опять без работы."), (B, "Шахта закрыта?"), (A, "Шахта на месте. Работы нет."), (B, "Давно, как у всех.")], pair=["sl_miner", "sl_trader"])

# ====================================================================== Вегас
T = "@vegas"
