conv("@all", "pair_np_shop", [(A, "Пирс, консервы просроченные."), (B, "Бабка Мэй, они не просроченные, они выдержанные."), (A, "Тогда пусть выдержат ещё.")], pair=["np_storekeeper", "np_old_mae"])

